pub fn bump_many(counter: &Mutex<u64>, threads: usize, per_thread: usize) {
    std::thread::scope(|scope| {
        for _ in 0..threads {
            scope.spawn(|| {
                for _ in 0..per_thread {
                    let mut guard = counter.lock().unwrap();
                    *guard -= 1;
                }
            });
        }
    });
}

